package com.example.notify.service;

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** 自定义拒绝策略：被拒绝的任务保留痕迹并可被监控统计。 */
public class NotifyDispatcher {

    private static final Logger log = LoggerFactory.getLogger(NotifyDispatcher.class);

    private final AtomicLong rejectedCount = new AtomicLong();

    private final ThreadPoolExecutor notifier = new ThreadPoolExecutor(
            8, 16, 60L, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(200),
            namedFactory("notify"),
            new CountingRejectionHandler());

    private static java.util.concurrent.ThreadFactory namedFactory(String prefix) {
        java.util.concurrent.atomic.AtomicInteger sequence = new java.util.concurrent.atomic.AtomicInteger();
        return task -> {
            Thread thread = new Thread(task);
            thread.setName(prefix + "-" + sequence.incrementAndGet());
            return thread;
        };
    }

    public void dispatch(String message) {
        notifier.execute(() -> handle(message));
    }

    private void handle(String message) {
        // 原始业务处理逻辑占位：实际发送通知
        log.debug("notify dispatched: {}", message);
    }

    public long stats() {
        return rejectedCount.get();
    }

    class CountingRejectionHandler implements RejectedExecutionHandler {
        @Override
        public void rejectedExecution(Runnable task, ThreadPoolExecutor executor) {
            long total = rejectedCount.incrementAndGet();
            log.warn("notify task rejected, total rejected={}, poolSize={}, activeCount={}, queueSize={}",
                    total, executor.getPoolSize(), executor.getActiveCount(), executor.getQueue().size());
        }
    }
}
